// <auto-generated/>
using Fanex.CustomerSetting.Module.Core;
using Fanex.Tarus.Infrastructure.Configurations.InternalLogin;
using Fanex.Tarus.Security.Criteria;
using Sunplus.Accounting.Business.Security;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Configurations;
using System;
using Role = Fanex.Tarus.Infrastructure.Common.Enumerations.Role;
using Fanex.Cryptography.Aes;
using System.Collections.Generic;
using System.Linq;

public partial class InternalView : PageBase
{
    protected void Page_Load(object sender, EventArgs e)
    {
        Role roleType = Request["roleId"] == null || Request["roleId"].Equals("undefined", StringComparison.CurrentCultureIgnoreCase) ? Role.Null : (Role)Utils.ToInt32(Request["roleId"]);
        string CustomerSite = Request["CustomerSite"] == null ? "" : Request["CustomerSite"]; 
        bool isDummyAcc = Permissions.CheckDummyAccount(new CheckDummyAccountCriteria() { CustName = Request["custName"] });

         if (isDummyAcc)
        {
            if (!Permissions.HasPermission("789ySites"))
            {
                Response.Write(GetGlobalResourceObject(Constants.Resources.LanguageResources, "DontHavePermission"));
                return;
            }
        }

        string strParams = string.Empty;
       
        strParams = Request["custName"] + "&" + Request["accId"] + "&" + Sunplus.Accounting.DataAccess.IBCDLL.SystemInfo.GetDBTime().Ticks;
        strParams = AesExtension.Encrypt(strParams, "!@#$");

        string internalAgentUrl = InternalLoginManager.GetInternalLoginUrl(CustomerSite, roleType);

        var internalPaths = internalAgentUrl.Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries);
        var internalDomains = internalPaths[0].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
        var internalLoginAction = internalPaths[1];
        var configDomains = new List<InternLoginDomain>();
        string randomDomain = null;
        string internalLoginSessionKey = "InternalLoginDomains_" + CustomerSite;

        if (Session[internalLoginSessionKey] != null)
        {
            configDomains = (List<InternLoginDomain>)Session[internalLoginSessionKey];
            var domainItem = configDomains.FirstOrDefault(domain => !domain.IsInUsed);

            randomDomain = domainItem == null ? null : domainItem.Domain;
        }
        else
        {
            foreach (var domain in internalDomains)
            {
                configDomains.Add(new InternLoginDomain { Domain = domain });
            }
        }

        randomDomain = randomDomain ?? internalDomains[new Random().Next(internalDomains.Length)];
        var foundDomain = configDomains.Find(item => item.Domain == randomDomain);
        if (foundDomain != null)
        {
            foundDomain.IsInUsed = true;
        }

        Session[internalLoginSessionKey] = configDomains;

        string url = string.Format("{0}?{1}parameter={2}&isVpn={3}",
            (randomDomain.StartsWith("http") ? randomDomain + internalLoginAction : "https://" + randomDomain + internalLoginAction),
            Session[WebSettings.InternalAgentUMToken] == null ? "" : string.Format("UMToken={0}&", Session[WebSettings.InternalAgentUMToken]),
            strParams,
            IsLocalOrVpnRequest(Request.Headers["Host"]));

        Response.Redirect(url);
        Response.End();
    }

    private static int IsLocalOrVpnRequest(string ip)
    {
        var ipReturn = string.IsNullOrWhiteSpace(ip) ? string.Empty : ip;
        return ipReturn.Split('.').Length == 4 &&
            (ipReturn.StartsWith("10.", StringComparison.OrdinalIgnoreCase) ||
            ipReturn.StartsWith("172.16.", StringComparison.OrdinalIgnoreCase) ||
            ipReturn.StartsWith("192.168.", StringComparison.OrdinalIgnoreCase)) ? 1 : 0;
    }
}